def solve(g):
    from collections import deque
    c=[-1]*len(g)
    for s in range(len(g)):
        if c[s]>=0: continue
        c[s]=0
        q=deque([s])
        while q:
            u=q.popleft()
            for v in g[u]:
                if c[v]<0:
                    c[v]=c[u]^1
                    q.append(v)
                elif c[v]==c[u]: return False
    return True
